function addActionBlock(o,type,start=time,options={}){if(!isAnimatedCharacter(o))return toast('Select a character or rigged picture first.');if(o.locked)return toast('Unlock this character first.');if(type==='walk'&&typeof canAnimateWalk==='function'&&!canAnimateWalk(o))return toast('Set up both thigh and shin joints before adding a walk.');if((o.actionBlocks||[]).length>=100)return toast('Keep up to 100 action blocks per character.');stop();start=clamp(start,clipStart(o),clipEnd(o)-.1);let duration=options.duration||easyActions[type]?.[2]||1;const end=start+duration,oldDuration=current().duration;if(end>clipEnd(o)&&clipEnd(o)===oldDuration&&end<=60){changeSceneDuration(current(),end);if(o.out===oldDuration)o.out=end}duration=Math.min(duration,clipEnd(o)-start);if(duration<.1)return toast('Place the playhead inside the character clip.');const block={id:uid(),type,start,duration,...options};if(type==='walk'&&!block.to){const v=stateAt(o,start);block.from={x:v.x,y:v.y};block.to={x:clamp(v.x+120,0,960),y:v.y}}if(type==='walk')o.footPins=[];(o.actionBlocks??=[]).push(block);o.characterLoop='none';if(type==='walk'&&o.motionPath)o.motionPath.enabled=false;selectedActionId=block.id;selected=o.id;selectedAudio=null;save();render();toast(easyActions[type][0]+' action added. Drag its block to change timing.');return block}
