const actionEvaluation=new Set(),stateBeforeActions=stateAt;stateAt=function(o,t){const v=stateBeforeActions(o,t);if(!isAnimatedCharacter(o)||actionEvaluation.has(o.id))return v;actionEvaluation.add(o.id);try{if(typeof evaluateCharacterActions==='function')evaluateCharacterActions(o,t,v);else{const blocks=(o.actionBlocks||[]).slice().sort((a,b)=>a.start-b.start),walk=blocks.filter(b=>b.type==='walk'&&b.start<=t).at(-1);if(walk&&!(o.keys||[]).some(k=>k.t>walk.start+walk.duration&&k.t<=t)){const f=clamp((t-walk.start)/walk.duration,0,1),move=f*f*(3-2*f);v.x=walk.from.x+(walk.to.x-walk.from.x)*move;v.y=walk.from.y+(walk.to.y-walk.from.y)*move;if(f>0&&f<1){const cycle=(t-walk.start)*Math.PI*3.2;v.leg+=Math.sin(cycle)*23;v.leftArm+=Math.sin(cycle)*24;v.rightArm-=Math.sin(cycle)*24;v.y-=Math.abs(Math.sin(cycle))*4}}for(const b of blocks){if(b.type==='walk'||t<b.start||t>=b.start+b.duration)continue;const f=(t-b.start)/b.duration,blend=Math.max(0,Math.min(1,f*6,(1-f)*6));if(b.type==='wave'){v.rightArm+=( -140-v.rightArm)*blend;v.rightElbow+=(-35+Math.sin(f*Math.PI*6)*22-v.rightElbow)*blend}else if(b.type==='point'){v.rightArm+=(-95-v.rightArm)*blend;v.rightElbow+=(-5-v.rightElbow)*blend;v.handOpen=blend}else if(b.type==='jump'){const height=Math.sin(f*Math.PI);v.y-=height*65;v.leftKnee+=Math.sin(f*Math.PI)*35;v.rightKnee+=Math.sin(f*Math.PI)*35;v.leftArm+=height*40;v.rightArm-=height*40}else if(b.type==='sit'){v.y+=blend*34;v.leftLeg-=blend*65;v.rightLeg-=blend*65;v.leftKnee+=blend*90;v.rightKnee+=blend*90}else if(b.type==='talk'){v.rightArm-=(25+Math.sin(f*Math.PI*5)*10)*blend;v.rightElbow-=25*blend;v.headTilt+=Math.sin(f*Math.PI*4)*4*blend;v.handOpen=blend}}
 }const look=current().objects.find(target=>target.id===o.lookTargetId),point=current().objects.find(target=>target.id===o.pointTargetId);if(look){const target=stateAt(look,t);v.headTurn=clamp((target.x-v.x)/220,-1,1);if(o.type==='puppet')v.headTilt+=v.headTurn*12;v.headTilt+=clamp((target.y-(v.y-240*v.scale))/60,-15,15)*.3}if(point){const target=stateAt(point,t);if(o.type==='character'){const local=characterWorldToLocal(target,v,o.character);v.rightArm=clamp(Math.atan2(local.y+171,local.x-36)*180/Math.PI-90,-175,175);v.rightElbow=0;v.handOpen=1}else{const part=o.parts.find(p=>p.channel==='rightArm')||o.parts.find(p=>p.channel==='leftArm');if(part){const matrix=puppetMatrices(o,v).matrices.get(part.id),p=matrix.inverse().transformPoint(target),tip=puppetTip(part),delta=(Math.atan2(p.y,p.x)-Math.atan2(tip.y,tip.x))*180/Math.PI;v[part.channel]+=delta}}}return v}finally{actionEvaluation.delete(o.id)}};
