const moveBeforeActions=moveVisual;moveVisual=function(o,change){const before=clipStart(o);moveBeforeActions(o,change);const delta=clipStart(o)-before;if(change.mode==='move'&&delta)for(const block of o.actionBlocks||[])block.start=clamp(block.start+delta,0,current().duration-block.duration)};
