function renderPoseLibrary(){const list=$('visualPoseLibrary');list.replaceChildren();for(const entry of [...builtInPoses,...savedPoseLibrary]){const wrapper=document.createElement('div'),button=document.createElement('button');button.className='pose-thumbnail';button.draggable=true;button.dataset.poseId=entry.id;const canvas=document.createElement('canvas');canvas.width=132;canvas.height=120;const c=canvas.getContext('2d');c.fillStyle='#242c36';c.fillRect(0,0,132,120);const o=object(),v={...pose,...rigDefaults,...entry.pose,x:66,y:117,scale:.35,opacity:1};if(o?.type==='puppet'){const width=Math.min(110,106*o.imageWidth/o.imageHeight);paintPuppet(c,{...o,width,lipSync:false},{...v,x:66,y:60,scale:1})}else character(c,o?.character||project.cast[0]||baseChar,v,'happy');const label=document.createElement('span');label.textContent=entry.name;button.append(canvas,label);button.onclick=()=>applyVisualPose(object(),entry);button.ondragstart=e=>{e.dataTransfer.setData('application/x-elleson-pose',entry.id);e.dataTransfer.effectAllowed='copy'};wrapper.append(button);if(entry.custom){const remove=document.createElement('button');remove.className='editcast';remove.textContent='Remove';remove.onclick=async()=>{savedPoseLibrary=savedPoseLibrary.filter(p=>p.id!==entry.id);await workspacePut('visualPoses',savedPoseLibrary);renderPoseLibrary()};wrapper.append(remove)}list.append(wrapper)}}
$('saveVisualPose').onclick=async()=>{const o=object();if(!isAnimatedCharacter(o))return toast('Select a character to save its pose.');if(savedPoseLibrary.length>=40)return toast('Keep up to 40 saved poses.');const v=stateAt(o,time),jointPose={};for(const key of Object.keys({...pose,...rigDefaults}))if(!['x','y','scale','rotation','opacity'].includes(key))jointPose[key]=v[key];const next=[...savedPoseLibrary,{id:uid(),name:$('savePoseName').value.trim()||'Pose '+(savedPoseLibrary.length+1),pose:jointPose,custom:true}];try{await workspacePut('visualPoses',next);savedPoseLibrary=next;renderPoseLibrary();toast('Pose saved.')}catch{toast('Could not save this pose library.')}};
