const timelineBeforeActionTracks=renderTimeline;renderTimeline=function(){timelineBeforeActionTracks();if(timelineDrag)return;const offset=sceneOffset();for(const o of current().objects.filter(isAnimatedCharacter)){const row=lane('↳ Actions · '+o.name,'action-track');row.row.dataset.actorId=o.id;const clip=document.querySelector('.timeline-clip[data-object-id="'+o.id+'"]');if(clip)clip.closest('.track-row').after(row.row);for(const block of o.actionBlocks||[]){const start=Math.max(clipStart(o),block.start),end=Math.min(clipEnd(o),block.start+block.duration);if(end<=start)continue;makeClip(row.area,{start:offset+start,end:offset+end,label:easyActions[block.type][0],kind:'action',active:selectedActionId===block.id,locked:o.locked,onselect:()=>{selectLayers([o.id]);selectedActionId=block.id;time=start},onmove:change=>{if(o.locked)return;const old=block.start;if(change.mode==='move')block.start=clamp(old+change.delta,clipStart(o),clipEnd(o)-block.duration);else if(change.mode==='right')block.duration=clamp(block.duration+change.delta,.1,clipEnd(o)-block.start);else{const next=clamp(block.start+change.delta,clipStart(o),block.start+block.duration-.1);block.duration+=block.start-next;block.start=next}}})}row.area.ondragover=e=>{if(Array.from(e.dataTransfer.types).some(t=>['application/x-elleson-action','application/x-elleson-pose'].includes(t))){e.preventDefault();e.dataTransfer.dropEffect='copy'}};row.area.ondrop=e=>{e.preventDefault();const t=clamp((e.clientX-row.area.getBoundingClientRect().left)/timelineZoom-offset,clipStart(o),clipEnd(o)-.1),type=e.dataTransfer.getData('application/x-elleson-action'),poseId=e.dataTransfer.getData('application/x-elleson-pose');if(Object.hasOwn(easyActions,type))addActionBlock(o,type,t);else{const pose=[...builtInPoses,...savedPoseLibrary].find(p=>p.id===poseId);if(pose)applyVisualPose(o,pose,t)}}}};
